function getPlainText(){return editor.innerText.replace(/\u00a0/g,' ').trim()}
function updateStats(){const text=getPlainText();const words=text?text.split(/\s+/).length:0;wordCount.textContent=`Слов: ${words}`;charCount.textContent=`Знаков: ${text.length}`;document.querySelector('#readingTime').textContent=`Чтение: ${words<180?'менее 1':Math.ceil(words/180)} мин`;document.querySelector('#pageCount').textContent=`Страниц примерно: ${Math.max(1,Math.ceil(editor.scrollHeight/1123))}`;document.querySelector('#goalStatus').textContent=wordGoal?`Цель: ${words} / ${wordGoal}`:'Цель: не задана';document.querySelector('#goalProgressBar').style.width=`${wordGoal?Math.min(100,words/wordGoal*100):0}%`}
function getDocumentData(){return{app:'MyWord 2026',version:15,title:titleInput.value,html:editor.innerHTML,margins:document.querySelector('#marginSelect').value,orientation:document.querySelector('#orientationSelect').value,pageSize:document.querySelector('#pageSizeSelect').value,pageColor:document.querySelector('#pageColor').value,columns:Number(document.querySelector('#columnsSelect').value),watermark:editor.dataset.watermark||'',pageBorder:editor.classList.contains('page-border'),wordGoal,meta:documentMeta,language:editor.lang||'ru-RU'}}
function queueAutoSave(){saveStatus.textContent='Сохранение…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>{localStorage.setItem(STORAGE_KEY,JSON.stringify(getDocumentData()));saveStatus.textContent='Документ сохранён'},500)}
function showToast(message){toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2200)}
editor.addEventListener('input',()=>{updateStats();updateOutline();queueAutoSave()});
editor.addEventListener('beforeinput',event=>{if(!trackChanges||applyingTrackedInput||event.inputType!=='insertText'||!event.data)return;event.preventDefault();applyingTrackedInput=true;document.execCommand('insertHTML',false,`<span class="tracked-insert">${escapeHtml(event.data)}</span>`);applyingTrackedInput=false;updateStats();queueAutoSave()});
editor.addEventListener('mouseup',rememberSelection);editor.addEventListener('keyup',rememberSelection);
