Object.assign(templates,{notes:{title:'Заметки',html:'<h1>Заметки</h1><p><b>Дата:</b> __________</p><h2>Главная мысль</h2><p>Введите заметку…</p><h2>Следующие действия</h2><div class="check-item"><input type="checkbox"><span>Новая задача</span></div>'},calendar:{title:'Календарь',html:'<h1>Календарь месяца</h1><table><tr><th>Пн</th><th>Вт</th><th>Ср</th><th>Чт</th><th>Пт</th><th>Сб</th><th>Вс</th></tr><tr><td>1</td><td>2</td><td>3</td><td>4</td><td>5</td><td>6</td><td>7</td></tr><tr><td>8</td><td>9</td><td>10</td><td>11</td><td>12</td><td>13</td><td>14</td></tr></table>'},checklist:{title:'Список задач',html:'<h1>Список задач</h1><p><b>Период:</b> __________</p><div class="check-item"><input type="checkbox"><span>Первая задача</span></div><div class="check-item"><input type="checkbox"><span>Вторая задача</span></div><div class="check-item"><input type="checkbox"><span>Третья задача</span></div>'},journal:{title:'Мой журнал',html:'<h1>Мой журнал</h1><p><b>Дата:</b> __________ &nbsp; <b>Настроение:</b> __________</p><h2>События дня</h2><p>Расскажите, как прошёл день…</p><h2>Важные мысли</h2><p>Введите текст…</p>'},newsletter:{title:'Информационный бюллетень',html:'<h1 style="color:#16a34a">ИНФОРМАЦИОННЫЙ БЮЛЛЕТЕНЬ</h1><p><b>Выпуск №1 · 2026</b></p><hr><h2>Главная новость</h2><p>Краткое описание главной новости.</p><h2>Другие события</h2><p>Введите информацию…</p>'},brochure:{title:'Буклет',html:'<h1 style="text-align:center;color:#7c3aed">ЗАГОЛОВОК БУКЛЕТА</h1><p style="text-align:center"><b>Краткое описание</b></p><hr><h2>О нас</h2><p>Расскажите о компании или проекте.</p><h2>Наши преимущества</h2><ul><li>Преимущество 1</li><li>Преимущество 2</li></ul><h2>Контакты</h2><p>Телефон: __________</p>'}});
document.querySelector('#templatesButton').addEventListener('click',()=>document.querySelector('#templatesModal').classList.remove('hidden'));document.querySelector('#closeTemplatesButton').addEventListener('click',()=>document.querySelector('#templatesModal').classList.add('hidden'));document.querySelector('#templatesModal').addEventListener('click',e=>{if(e.target.id==='templatesModal')e.currentTarget.classList.add('hidden')});document.querySelectorAll('[data-template]').forEach(button=>button.addEventListener('click',()=>{if(getPlainText()&&!confirm('Заменить текущий документ выбранным шаблоном?'))return;const template=templates[button.dataset.template];titleInput.value=template.title;editor.innerHTML=template.html;document.querySelector('#templatesModal').classList.add('hidden');updateStats();updateOutline();queueAutoSave();showToast('Шаблон применён')}));
document.querySelector('#saveButton').addEventListener('click',()=>{const file=`<!DOCTYPE html><html lang="ru"><head><meta charset="UTF-8"><title>${escapeHtml(titleInput.value)}</title><style>body{max-width:760px;margin:50px auto;padding:30px;font-family:Calibri,Arial,sans-serif;line-height:1.55}</style></head><body>${editor.innerHTML}</body></html>`;downloadFile(file,safeName(titleInput.value)+'.html','text/html');showToast('Документ сохранён в формате HTML')});
document.querySelector('#projectButton').addEventListener('click',()=>{downloadFile(JSON.stringify(getDocumentData(),null,2),safeName(titleInput.value)+'.myword.json','application/json');showToast('Проект сохранён со всеми настройками')});
document.querySelector('#saveCopyButton').addEventListener('click',()=>{const stamp=new Date().toISOString().slice(0,16).replace(/[T:]/g,'-');downloadFile(JSON.stringify(getDocumentData(),null,2),`${safeName(titleInput.value)}-копия-${stamp}.myword.json`,'application/json');showToast('Отдельная копия сохранена')});
document.querySelector('#lockedButton').addEventListener('click',async()=>{if(!globalThis.crypto?.subtle){showToast('Шифрование недоступно в этом режиме браузера');return}const password=prompt('Придумайте пароль для файла:');if(!password||password.length<4){showToast('Пароль должен содержать минимум 4 символа');return}try{const encrypted=await encryptProject(getDocumentData(),password);downloadFile(JSON.stringify(encrypted),safeName(titleInput.value)+'.myword.locked','application/json');showToast('Защищённый файл сохранён')}catch{showToast('Не удалось зашифровать документ')}});
async function passwordKey(password,salt,usage){const base=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:120000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,[usage])}
function toBase64(bytes){const array=new Uint8Array(bytes);let binary='';for(let index=0;index<array.length;index+=32768)binary+=String.fromCharCode(...array.subarray(index,index+32768));return btoa(binary)}const fromBase64=value=>Uint8Array.from(atob(value),char=>char.charCodeAt(0));
async function encryptProject(data,password){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await passwordKey(password,salt,'encrypt'),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(data)));return{app:'MyWord Locked',salt:toBase64(salt),iv:toBase64(iv),data:toBase64(cipher)}}
async function decryptProject(payload,password){const salt=fromBase64(payload.salt),iv=fromBase64(payload.iv),key=await passwordKey(password,salt,'decrypt'),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,fromBase64(payload.data));return JSON.parse(new TextDecoder().decode(plain))}
document.querySelector('#documentsButton').addEventListener('click',()=>{renderDocuments();document.querySelector('#documentsModal').classList.remove('hidden')});document.querySelector('#closeDocumentsButton').addEventListener('click',()=>document.querySelector('#documentsModal').classList.add('hidden'));document.querySelector('#saveBrowserDocumentButton').addEventListener('click',()=>{const docs=getBrowserDocuments(),data=getDocumentData();docs.unshift({...data,id:Date.now(),savedAt:new Date().toISOString()});localStorage.setItem(DOCUMENTS_KEY,JSON.stringify(docs.slice(0,20)));renderDocuments();showToast('Документ сохранён в браузере')});
function getBrowserDocuments(){try{return JSON.parse(localStorage.getItem(DOCUMENTS_KEY))||[]}catch{return[]}}function renderDocuments(){const list=document.querySelector('#documentsList'),docs=getBrowserDocuments();list.innerHTML=docs.length?'':'<div class="history-empty">Сохранённых документов пока нет.</div>';docs.forEach((doc,index)=>{const row=document.createElement('div');row.className='history-item';row.innerHTML=`<div><strong>${escapeHtml(doc.title)}</strong><span>${new Date(doc.savedAt).toLocaleString('ru-RU')}</span></div><button data-doc-open="${index}">Открыть</button><button data-doc-delete="${index}">×</button>`;list.append(row)});list.querySelectorAll('[data-doc-open]').forEach(button=>button.onclick=()=>{loadDocumentData(getBrowserDocuments()[button.dataset.docOpen]);document.querySelector('#documentsModal').classList.add('hidden')});list.querySelectorAll('[data-doc-delete]').forEach(button=>button.onclick=()=>{const docs=getBrowserDocuments();docs.splice(button.dataset.docDelete,1);localStorage.setItem(DOCUMENTS_KEY,JSON.stringify(docs));renderDocuments()})}
document.querySelector('#saveCustomTemplateButton').addEventListener('click',()=>{localStorage.setItem(CUSTOM_TEMPLATE_KEY,JSON.stringify(getDocumentData()));showToast('Собственный шаблон сохранён')});
document.querySelector('#customTemplateButton').addEventListener('click',()=>{const saved=localStorage.getItem(CUSTOM_TEMPLATE_KEY);if(!saved){showToast('Сначала сохраните собственный шаблон');return}if(getPlainText()&&!confirm('Заменить текущий документ вашим шаблоном?'))return;try{loadDocumentData(JSON.parse(saved));document.querySelector('#templatesModal').classList.add('hidden');showToast('Ваш шаблон применён')}catch{showToast('Не удалось открыть шаблон')}});
document.querySelector('#historyButton').addEventListener('click',()=>{renderHistory();document.querySelector('#historyModal').classList.remove('hidden')});
document.querySelector('#closeHistoryButton').addEventListener('click',()=>document.querySelector('#historyModal').classList.add('hidden'));
document.querySelector('#historyModal').addEventListener('click',event=>{if(event.target.id==='historyModal')event.currentTarget.classList.add('hidden')});
document.querySelector('#saveVersionButton').addEventListener('click',()=>saveVersion());
function getHistory(){try{return JSON.parse(localStorage.getItem(HISTORY_KEY))||[]}catch{return[]}}
function saveVersion(){const history=getHistory(),data=getDocumentData();if(history[0]?.html===data.html&&history[0]?.title===data.title){showToast('Документ не изменился');return}history.unshift({...data,savedAt:new Date().toISOString()});localStorage.setItem(HISTORY_KEY,JSON.stringify(history.slice(0,12)));renderHistory();showToast('Версия сохранена')}
function renderHistory(){const list=document.querySelector('#historyList'),history=getHistory();if(!history.length){list.innerHTML='<div class="history-empty">Сохранённых версий пока нет.</div>';return}list.innerHTML='';history.forEach((item,index)=>{const row=document.createElement('div');row.className='history-item';row.innerHTML=`<div><strong>${escapeHtml(item.title||'Документ')}</strong><span>${new Date(item.savedAt).toLocaleString('ru-RU')}</span></div><button data-restore="${index}">Восстановить</button><button data-remove="${index}">×</button>`;list.append(row)});list.querySelectorAll('[data-restore]').forEach(button=>button.onclick=()=>{const item=getHistory()[button.dataset.restore];if(!item||!confirm('Восстановить эту версию документа?'))return;titleInput.value=item.title;editor.innerHTML=item.html;applyPageSettings(item.margins,item.orientation,item.pageColor);applyColumns(item.columns||1);applyDocumentExtras(item);queueAutoSave();updateStats();updateOutline();document.querySelector('#historyModal').classList.add('hidden');showToast('Версия восстановлена')});list.querySelectorAll('[data-remove]').forEach(button=>button.onclick=()=>{const history=getHistory();history.splice(button.dataset.remove,1);localStorage.setItem(HISTORY_KEY,JSON.stringify(history));renderHistory()})}
document.querySelector('#txtButton').addEventListener('click',()=>{downloadFile(getPlainText(),safeName(titleInput.value)+'.txt','text/plain');showToast('Текст сохранён в формате TXT')});
document.querySelector('#markdownButton').addEventListener('click',()=>{downloadFile(editorToMarkdown(),safeName(titleInput.value)+'.md','text/markdown');showToast('Документ сохранён в Markdown')});
document.querySelector('#docButton').addEventListener('click',()=>{if(!window.htmlDocx){showToast('Модуль DOCX ещё загружается — повторите через несколько секунд');return}const file=`<!DOCTYPE html><html lang="${editor.lang||'ru'}"><head><meta charset="UTF-8"><title>${escapeHtml(titleInput.value)}</title><style>body{font-family:Calibri,Arial;font-size:12pt;line-height:1.55;margin:2cm}table{border-collapse:collapse;width:100%}td,th{border:1px solid #777;padding:7px}img{max-width:100%}</style></head><body>${editor.innerHTML}</body></html>`;const blob=htmlDocx.asBlob(file,{orientation:'portrait',margins:{top:1134,right:1134,bottom:1134,left:1134}}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=safeName(titleInput.value)+'.docx';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),500);showToast('Документ DOCX сохранён')});
document.querySelector('#duplicateButton').addEventListener('click',()=>{const docs=getBrowserDocuments(),data=getDocumentData();docs.unshift({...data,title:`${data.title} — копия`,id:Date.now(),savedAt:new Date().toISOString()});localStorage.setItem(DOCUMENTS_KEY,JSON.stringify(docs.slice(0,20)));showToast('Дубликат сохранён в разделе «Документы»')});
document.querySelector('#openButton').addEventListener('click',()=>document.querySelector('#fileInput').click());
document.querySelector('#fileInput').addEventListener('change',event=>{const file=event.target.files[0];if(!file)return;const lower=file.name.toLowerCase(),reader=new FileReader();reader.onload=async()=>{try{if(lower.endsWith('.docx')){if(!window.mammoth)throw Error('DOCX module');const result=await mammoth.convertToHtml({arrayBuffer:reader.result});titleInput.value=file.name.replace(/\.[^.]+$/,'');editor.innerHTML=result.value||'<p></p>'}else if(lower.endsWith('.locked')){const password=prompt('Введите пароль файла:');if(!password)return;loadDocumentData(await decryptProject(JSON.parse(reader.result),password))}else if(lower.endsWith('.json')){const data=JSON.parse(reader.result);if(data.app!=='MyWord 2026')throw Error();loadDocumentData(data)}else{titleInput.value=file.name.replace(/\.[^.]+$/,'');if(lower.endsWith('.txt'))editor.innerText=reader.result;else{const parsed=new DOMParser().parseFromString(reader.result,'text/html');editor.innerHTML=parsed.body.innerHTML}}updateStats();queueAutoSave();showToast(lower.endsWith('.docx')?'Документ Word открыт':'Файл открыт')}catch{showToast('Не удалось открыть файл. Проверьте его формат')}};if(lower.endsWith('.docx'))reader.readAsArrayBuffer(file);else reader.readAsText(file);event.target.value=''});
document.querySelector('#printButton').addEventListener('click',()=>window.print());
document.querySelector('#themeButton').addEventListener('click',event=>{document.body.classList.toggle('dark');const dark=document.body.classList.contains('dark');event.currentTarget.textContent=dark?'☀️':'🌙';localStorage.setItem('myword2026-theme',dark?'dark':'light')});
document.querySelector('#speakButton').addEventListener('click',event=>{if(!('speechSynthesis'in window)){showToast('Чтение вслух не поддерживается');return}if(speechSynthesis.speaking){speechSynthesis.cancel();event.currentTarget.classList.remove('speaking');event.currentTarget.textContent='🔊 Читать';return}const selection=window.getSelection(),text=selection&&!selection.isCollapsed&&editor.contains(selection.anchorNode)?selection.toString():getPlainText();if(!text){showToast('В документе нет текста');return}const utterance=new SpeechSynthesisUtterance(text);utterance.lang='ru-RU';utterance.rate=1;utterance.onend=()=>{event.currentTarget.classList.remove('speaking');event.currentTarget.textContent='🔊 Читать'};speechSynthesis.speak(utterance);event.currentTarget.classList.add('speaking');event.currentTarget.textContent='■ Стоп'});
document.querySelector('#focusTimerButton').addEventListener('click',()=>{if(focusTimer){clearInterval(focusTimer);focusTimer=null;focusSeconds=0;updateFocusTimer();showToast('Таймер остановлен');return}const minutes=Math.max(1,Math.min(120,Number(prompt('Сколько минут работать без перерыва?',25))||0));if(!minutes)return;focusSeconds=minutes*60;updateFocusTimer();focusTimer=setInterval(()=>{focusSeconds--;updateFocusTimer();if(focusSeconds<=0){clearInterval(focusTimer);focusTimer=null;showToast('Время закончилось — сделайте перерыв!');document.querySelector('#focusTimerButton').textContent='⏱ 25:00'}},1000);showToast(`Таймер запущен на ${minutes} мин`)});
function updateFocusTimer(){const minutes=Math.floor(focusSeconds/60),seconds=focusSeconds%60,label=`${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`;document.querySelector('#timerStatus').textContent=focusTimer?`Фокус: ${label}`:'';document.querySelector('#focusTimerButton').textContent=focusTimer?`■ ${label}`:'⏱ 25:00'}
document.querySelector('#restoreBackupButton').addEventListener('click',()=>{const saved=localStorage.getItem('myword2026-emergency-backup');if(!saved){showToast('Аварийная копия пока не создана');return}if(!confirm('Восстановить последнюю аварийную копию?'))return;try{loadDocumentData(JSON.parse(saved));showToast('Аварийная копия восстановлена')}catch{showToast('Копия повреждена')}});
document.querySelector('#fullscreenButton').addEventListener('click',()=>{document.body.classList.toggle('focus-mode');if(document.body.classList.contains('focus-mode'))document.documentElement.requestFullscreen?.().catch(()=>{});else if(document.fullscreenElement)document.exitFullscreen?.()});document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)document.body.classList.remove('focus-mode')});
document.querySelectorAll('.tab[data-message]').forEach(tab=>tab.addEventListener('click',()=>showToast(tab.dataset.message)));
zoomRange.addEventListener('input',()=>{const value=zoomRange.value;editor.style.transform=`scale(${value/100})`;editor.parentElement.style.marginBottom=`${1123*(value/100-1)}px`;zoomValue.value=`${value}%`});

function rememberSelection(){const selection=window.getSelection();if(selection.rangeCount&&editor.contains(selection.anchorNode))savedRange=selection.getRangeAt(0).cloneRange()}
function restoreSelection(){editor.focus();if(!savedRange)return;const selection=window.getSelection();selection.removeAllRanges();selection.addRange(savedRange)}
document.querySelector('#imageButton').addEventListener('click',()=>{rememberSelection();document.querySelector('#imageInput').click()});
document.querySelector('#imageInput').addEventListener('change',event=>{const file=event.target.files[0];if(!file)return;if(file.size>5*1024*1024){showToast('Изображение должно быть меньше 5 МБ');return}const reader=new FileReader();reader.onload=()=>{restoreSelection();document.execCommand('insertImage',false,reader.result);updateStats();queueAutoSave();showToast('Изображение вставлено')};reader.readAsDataURL(file);event.target.value=''});
document.querySelectorAll('[data-image-size]').forEach(button=>button.addEventListener('click',()=>{if(!selectedImage)return;selectedImage.style.width=button.dataset.imageSize;selectedImage.style.height='auto';queueAutoSave()}));document.querySelectorAll('[data-image-align]').forEach(button=>button.addEventListener('click',()=>{if(!selectedImage)return;const align=button.dataset.imageAlign;selectedImage.style.marginLeft=align==='left'?'0':align==='center'?'auto':'auto';selectedImage.style.marginRight=align==='right'?'0':align==='center'?'auto':'auto';queueAutoSave()}));document.querySelector('#deleteImageButton').addEventListener('click',()=>{selectedImage?.remove();selectedImage=null;document.querySelector('#imageToolbar').classList.add('hidden');queueAutoSave();updateStats()});
document.querySelector('#tableButton').addEventListener('click',()=>{rememberSelection();const rows=Math.min(15,Math.max(1,Number(prompt('Сколько строк?',3))||0));if(!rows)return;const columns=Math.min(10,Math.max(1,Number(prompt('Сколько столбцов?',3))||0));if(!columns)return;let html='<table><tbody>';for(let r=0;r<rows;r++){html+='<tr>';for(let c=0;c<columns;c++)html+=`<${r===0?'th':'td'}>${r===0?'Заголовок':'Текст'}</${r===0?'th':'td'}>`;html+='</tr>'}html+='</tbody></table><p><br></p>';restoreSelection();document.execCommand('insertHTML',false,html);queueAutoSave();showToast('Таблица вставлена')});
