document.querySelector('#findButton').addEventListener('click',()=>{const find=prompt('Какой текст найти?');if(!find)return;const replacement=prompt('На какой текст заменить? Оставьте пустым, чтобы удалить.',find);if(replacement===null)return;const walker=document.createTreeWalker(editor,NodeFilter.SHOW_TEXT);let count=0,node;const expression=new RegExp(escapeRegExp(find),'gi');while(node=walker.nextNode()){if(expression.test(node.nodeValue)){node.nodeValue=node.nodeValue.replace(expression,()=>{count++;return replacement})}expression.lastIndex=0}updateStats();queueAutoSave();showToast(count?`Заменено: ${count}`:'Текст не найден')});
