document.querySelector('#commentButton').addEventListener('click',()=>{const selection=window.getSelection();if(selection.isCollapsed||!editor.contains(selection.anchorNode)){showToast('Сначала выделите текст');return}const comment=prompt('Введите комментарий:');if(!comment)return;const selected=selection.toString();document.execCommand('insertHTML',false,`<span class="comment-mark" data-comment="${escapeHtml(comment)}">${escapeHtml(selected)}</span>`);queueAutoSave();renderComments();showToast('Комментарий добавлен')});
