function renderComments(){const list=document.querySelector('#commentsList'),marks=[...editor.querySelectorAll('.comment-mark')];list.innerHTML=marks.length?'':'<div class="history-empty">Комментариев пока нет.</div>';marks.forEach((mark,index)=>{mark.dataset.commentId=index;const item=document.createElement('div');item.className='comment-item';item.innerHTML=`<strong>«${escapeHtml(mark.innerText.slice(0,45))}»</strong><span>${escapeHtml(mark.dataset.comment||'')}</span><button data-comment-go="${index}">Показать</button> <button data-comment-delete="${index}">Удалить</button>`;list.append(item)});list.querySelectorAll('[data-comment-go]').forEach(button=>button.onclick=()=>editor.querySelector(`[data-comment-id="${button.dataset.commentGo}"]`)?.scrollIntoView({behavior:'smooth',block:'center'}));list.querySelectorAll('[data-comment-delete]').forEach(button=>button.onclick=()=>{const mark=editor.querySelector(`[data-comment-id="${button.dataset.commentDelete}"]`);if(mark)mark.replaceWith(document.createTextNode(mark.innerText));renderComments();queueAutoSave()})}
document.querySelector('#addBookmarkButton').addEventListener('click',()=>{const name=prompt('Название закладки:','Важное место');if(!name)return;restoreSelection();const selection=window.getSelection(),id=`bookmark-${Date.now()}`;if(selection&&!selection.isCollapsed&&editor.contains(selection.anchorNode))document.execCommand('insertHTML',false,`<span id="${id}" class="document-bookmark" data-bookmark="${escapeHtml(name)}">${escapeHtml(selection.toString())}</span>`);else document.execCommand('insertHTML',false,`<span id="${id}" class="document-bookmark" data-bookmark="${escapeHtml(name)}">🔖 ${escapeHtml(name)}</span>`);queueAutoSave();renderBookmarks();showToast('Закладка добавлена')});document.querySelector('#bookmarksButton').addEventListener('click',()=>{renderBookmarks();document.querySelector('#bookmarksPanel').classList.toggle('hidden')});document.querySelector('#closeBookmarksButton').addEventListener('click',()=>document.querySelector('#bookmarksPanel').classList.add('hidden'));
function renderBookmarks(){const list=document.querySelector('#bookmarksList'),marks=[...editor.querySelectorAll('.document-bookmark')];list.innerHTML=marks.length?'':'<div class="history-empty">Закладок пока нет.</div>';marks.forEach((mark,index)=>{mark.dataset.bookmarkIndex=index;const item=document.createElement('div');item.className='comment-item';item.innerHTML=`<strong>${escapeHtml(mark.dataset.bookmark||`Закладка ${index+1}`)}</strong><span>${escapeHtml(mark.innerText.slice(0,55))}</span><button data-bookmark-go="${index}">Перейти</button> <button data-bookmark-delete="${index}">Удалить</button>`;list.append(item)});list.querySelectorAll('[data-bookmark-go]').forEach(button=>button.onclick=()=>editor.querySelector(`[data-bookmark-index="${button.dataset.bookmarkGo}"]`)?.scrollIntoView({behavior:'smooth',block:'center'}));list.querySelectorAll('[data-bookmark-delete]').forEach(button=>button.onclick=()=>{const mark=editor.querySelector(`[data-bookmark-index="${button.dataset.bookmarkDelete}"]`);mark?.replaceWith(document.createTextNode(mark.innerText));renderBookmarks();queueAutoSave()})}
