document.querySelector('#statsButton').addEventListener('click',()=>{showDocumentStats();document.querySelector('#statsModal').classList.remove('hidden')});document.querySelector('#closeStatsButton').addEventListener('click',()=>document.querySelector('#statsModal').classList.add('hidden'));document.querySelector('#statsModal').addEventListener('click',event=>{if(event.target.id==='statsModal')event.currentTarget.classList.add('hidden')});
function showDocumentStats(){document.querySelector('#statsModalTitle').textContent='Статистика документа';document.querySelector('#statsGrid').classList.remove('hidden');document.querySelector('#frequencyList').classList.add('hidden');const text=getPlainText(),words=text?text.split(/\s+/).length:0,sentences=(text.match(/[.!?]+(?=\s|$)/g)||[]).length,paragraphs=[...editor.querySelectorAll('p,h1,h2,h3,li')].filter(x=>x.innerText.trim()).length,images=editor.querySelectorAll('img').length,tables=editor.querySelectorAll('table').length,pages=Math.max(1,Math.ceil(editor.scrollHeight/1123));const items=[['Слов',words],['Знаков',text.length],['Предложений',sentences],['Абзацев',paragraphs],['Страниц',pages],['Время чтения',words<180?'< 1 мин':Math.ceil(words/180)+' мин'],['Изображений',images],['Таблиц',tables],['Комментариев',editor.querySelectorAll('.comment-mark').length]];document.querySelector('#statsGrid').innerHTML=items.map(([label,value])=>`<div class="stat-box"><strong>${value}</strong><span>${label}</span></div>`).join('')}
document.querySelector('#frequencyButton').addEventListener('click',()=>{const stop=new Set(['и','в','во','на','с','со','а','но','это','как','к','по','из','за','для','не','что','я','мы','вы','он','она','они']),words=(getPlainText().toLowerCase().match(/[а-яёa-z]{3,}/gi)||[]).filter(word=>!stop.has(word)),counts={};words.forEach(word=>counts[word]=(counts[word]||0)+1);const top=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,12),max=top[0]?.[1]||1,list=document.querySelector('#frequencyList');document.querySelector('#statsModalTitle').textContent='Часто повторяющиеся слова';document.querySelector('#statsGrid').classList.add('hidden');list.classList.remove('hidden');list.innerHTML=top.length?top.map(([word,count])=>`<div class="frequency-row"><strong>${escapeHtml(word)}</strong><i style="width:${count/max*100}%"></i><span>${count}×</span></div>`).join(''):'<div class="history-empty">Недостаточно текста для анализа</div>';document.querySelector('#statsModal').classList.remove('hidden')});
document.querySelector('#accessibilityButton').addEventListener('click',()=>{const issues=[],images=[...editor.querySelectorAll('img')].filter(img=>!img.alt),emptyLinks=[...editor.querySelectorAll('a')].filter(link=>!link.innerText.trim()),longParagraphs=[...editor.querySelectorAll('p')].filter(p=>p.innerText.length>500),tables=[...editor.querySelectorAll('table')].filter(table=>!table.querySelector('th'));if(!editor.querySelector('h1'))issues.push('Добавьте главный заголовок H1');if(images.length)issues.push(`Изображения без описания: ${images.length}`);if(emptyLinks.length)issues.push(`Ссылки без понятного текста: ${emptyLinks.length}`);if(longParagraphs.length)issues.push(`Слишком длинные абзацы: ${longParagraphs.length}`);if(tables.length)issues.push(`Таблицы без строки заголовков: ${tables.length}`);const result=document.querySelector('#accessibilityResults');result.innerHTML=issues.length?issues.map(text=>`<div class="accessibility-item warn">⚠ ${escapeHtml(text)}</div>`).join(''):'<div class="accessibility-item good">✓ Основных проблем доступности не найдено</div>';document.querySelector('#accessibilityModal').classList.remove('hidden')});document.querySelector('#closeAccessibilityButton').addEventListener('click',()=>document.querySelector('#accessibilityModal').classList.add('hidden'));
