document.querySelector('#propertiesButton').addEventListener('click',()=>{document.querySelector('#documentAuthor').value=documentMeta.author||'';document.querySelector('#documentSubject').value=documentMeta.subject||'';document.querySelector('#documentKeywords').value=documentMeta.keywords||'';document.querySelector('#propertiesModal').classList.remove('hidden')});document.querySelector('#closePropertiesButton').addEventListener('click',()=>document.querySelector('#propertiesModal').classList.add('hidden'));document.querySelector('#savePropertiesButton').addEventListener('click',()=>{documentMeta={author:document.querySelector('#documentAuthor').value.trim(),subject:document.querySelector('#documentSubject').value.trim(),keywords:document.querySelector('#documentKeywords').value.trim()};document.querySelector('#propertiesModal').classList.add('hidden');queueAutoSave();showToast('Свойства документа сохранены')});
document.querySelector('#caseSelect').addEventListener('change',event=>{const mode=event.target.value,selection=window.getSelection();if(!mode||selection.isCollapsed||!editor.contains(selection.anchorNode)){showToast('Сначала выделите текст');event.target.value='';return}const original=selection.toString();let changed=original;if(mode==='upper')changed=original.toUpperCase();if(mode==='lower')changed=original.toLowerCase();if(mode==='sentence')changed=original.toLowerCase().replace(/(^|[.!?]\s+)\p{L}/gu,match=>match.toUpperCase());if(mode==='title')changed=original.toLowerCase().replace(/(^|\s)\p{L}/gu,match=>match.toUpperCase());document.execCommand('insertText',false,changed);event.target.value='';queueAutoSave();updateStats()});
document.querySelector('#cleanSpacesButton').addEventListener('click',()=>{if(!confirm('Убрать повторяющиеся пробелы во всём документе?'))return;const walker=document.createTreeWalker(editor,NodeFilter.SHOW_TEXT);let node,count=0;while(node=walker.nextNode()){const cleaned=node.nodeValue.replace(/[ \t]{2,}/g,' ').replace(/ +([,.;:!?])/g,'$1');if(cleaned!==node.nodeValue){node.nodeValue=cleaned;count++}}queueAutoSave();updateStats();showToast(`Исправлено фрагментов: ${count}`)});
