document.querySelector('#trackChangesButton').addEventListener('click',event=>{trackChanges=!trackChanges;event.currentTarget.classList.toggle('active-tool',trackChanges);event.currentTarget.textContent=trackChanges?'🟢 Исправления включены':'📝 Исправления';showToast(trackChanges?'Новый текст будет отмечаться':'Режим исправлений выключен')});
