function showRibbon(name='home'){document.querySelectorAll('.ribbon>.tool-group').forEach(group=>group.style.display='none');(ribbonGroups[name]||ribbonGroups.home).forEach(selector=>{const group=document.querySelector(selector);if(group)group.style.display='flex'})}
document.querySelectorAll('.tab[data-ribbon]').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));tab.classList.add('active');showRibbon(tab.dataset.ribbon)}));
document.querySelectorAll('[data-word-style]').forEach(button=>button.addEventListener('click',()=>{runCommand('formatBlock',button.dataset.wordStyle);document.querySelector('#blockFormat').value=['p','h1','h2','h3'].includes(button.dataset.wordStyle)?button.dataset.wordStyle:'p'}));
const fileMenu=document.querySelector('#fileMenu'),fileMenuButton=document.querySelector('#fileMenuButton');fileMenuButton.addEventListener('click',event=>{event.stopPropagation();fileMenu.classList.toggle('hidden');fileMenuButton.classList.toggle('open',!fileMenu.classList.contains('hidden'))});document.querySelectorAll('[data-file-action]').forEach(button=>button.addEventListener('click',()=>{fileMenu.classList.add('hidden');fileMenuButton.classList.remove('open');document.querySelector(`#${button.dataset.fileAction}`)?.click()}));document.addEventListener('click',event=>{if(!fileMenu.contains(event.target)&&event.target!==fileMenuButton){fileMenu.classList.add('hidden');fileMenuButton.classList.remove('open')}});
document.querySelectorAll('[data-mac-command]').forEach(button=>button.addEventListener('click',()=>{const map={edit:'home',view:'view',insert:'insert',format:'home',tools:'review',table:'insert',window:'view'};const target=map[button.dataset.macCommand];if(target){document.querySelector(`.tab[data-ribbon="${target}"]`)?.click()}else showToast('Раздел «Справка» добавим позже')}));
function updateMenuClock(){document.querySelector('#menuClock').textContent=new Date().toLocaleString('ru-RU',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}updateMenuClock();setInterval(updateMenuClock,30000);
const quickCommands=[['📄','Новый документ','Создать пустой документ','newButton'],['▦','Шаблоны','Открыть галерею шаблонов','templatesButton'],['📂','Открыть файл','HTML, TXT или проект MyWord','openButton'],['💾','Сохранить проект','Сохранить все настройки','projectButton'],['🔒','Защитить паролем','Создать зашифрованный файл','lockedButton'],['🖨️','Печать или PDF','Открыть окно печати','printButton'],['🔎','Найти и заменить','Поиск по документу','findButton'],['🖼','Вставить изображение','Добавить фотографию','imageButton'],['▦','Вставить таблицу','Создать таблицу','tableButton'],['☑','Добавить чек-лист','Список задач с флажками','checklistButton'],['☷','Создать оглавление','Собрать заголовки документа','tocButton'],['🌙','Сменить тему','Светлый или тёмный режим','themeButton'],['📊','Статистика','Подробный анализ документа','statsButton'],['👁','Режим чтения','Скрыть инструменты редактора','readingModeButton']];
function openCommandPalette(){document.querySelector('#commandModal').classList.remove('hidden');const input=document.querySelector('#commandSearch');input.value='';renderCommands('');setTimeout(()=>input.focus(),30)}
function renderCommands(query=''){const list=document.querySelector('#commandList'),term=query.trim().toLowerCase(),items=quickCommands.filter(item=>(item[1]+' '+item[2]).toLowerCase().includes(term));list.innerHTML=items.length?'':'<div class="history-empty">Команда не найдена</div>';items.forEach(([icon,name,description,id])=>{const button=document.createElement('button');button.className='command-item';button.innerHTML=`<b>${icon}</b><div><strong>${name}</strong><span>${description}</span></div>`;button.onclick=()=>{document.querySelector('#commandModal').classList.add('hidden');document.querySelector(`#${id}`)?.click()};list.append(button)})}
document.querySelector('#commandButton').addEventListener('click',openCommandPalette);document.querySelector('#closeCommandButton').addEventListener('click',()=>document.querySelector('#commandModal').classList.add('hidden'));document.querySelector('#commandSearch').addEventListener('input',event=>renderCommands(event.target.value));document.querySelector('#commandModal').addEventListener('click',event=>{if(event.target.id==='commandModal')event.currentTarget.classList.add('hidden')});
document.addEventListener('selectionchange',()=>{const selection=window.getSelection(),text=selection&&editor.contains(selection.anchorNode)?selection.toString().trim():'';const words=text?text.split(/\s+/).length:0;document.querySelector('#selectionCount').textContent=text?`Выделено: ${words} сл. · ${text.length} зн.`:'Выделено: 0'});editor.addEventListener('change',event=>{if(event.target.matches('.check-item input'))queueAutoSave()});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelector('#commandModal').classList.add('hidden');if(!(event.ctrlKey||event.metaKey))return;const key=event.key.toLowerCase();if(key==='k'){event.preventDefault();openCommandPalette()}else if(key==='w'&&event.shiftKey){event.preventDefault();document.querySelector('#docButton').click()}else if(key==='s'){event.preventDefault();document.querySelector('#projectButton').click()}else if(key==='f'){event.preventDefault();document.querySelector('#findButton').click()}else if(key==='p'){event.preventDefault();window.print()}else if(key==='b'){event.preventDefault();runCommand('bold')}else if(key==='i'){event.preventDefault();runCommand('italic')}else if(key==='u'){event.preventDefault();runCommand('underline')}});
const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;let recognition=null;if(SpeechRecognition){recognition=new SpeechRecognition();recognition.lang='ru-RU';recognition.continuous=true;recognition.interimResults=false;recognition.onresult=event=>{restoreSelection();for(let i=event.resultIndex;i<event.results.length;i++)if(event.results[i].isFinal)document.execCommand('insertText',false,event.results[i][0].transcript+' ');updateStats();queueAutoSave()};recognition.onend=()=>document.querySelector('#voiceButton').classList.remove('voice-active')}document.querySelector('#voiceButton').addEventListener('click',()=>{if(!recognition){showToast('Голосовой ввод не поддерживается этим браузером');return}rememberSelection();const button=document.querySelector('#voiceButton');if(button.classList.contains('voice-active')){recognition.stop();button.classList.remove('voice-active')}else{recognition.start();button.classList.add('voice-active');showToast('Говорите — текст будет добавлен')}});

function downloadFile(content,name,type){const blob=new Blob([content],{type:`${type};charset=utf-8`});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),500)}
function safeName(name){return(name.trim()||'document').replace(/[\\/:*?"<>|]/g,'-')}
function escapeHtml(value){return value.replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]))}
function escapeRegExp(value){return value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}
function editorToMarkdown(){function convert(node,depth=0){if(node.nodeType===Node.TEXT_NODE)return node.nodeValue;if(node.nodeType!==Node.ELEMENT_NODE)return'';const tag=node.tagName.toLowerCase(),inside=[...node.childNodes].map(child=>convert(child,depth)).join('');if(tag==='h1'||tag==='h2'||tag==='h3')return`${'#'.repeat(Number(tag[1]))} ${inside.trim()}\n\n`;if(tag==='p'||tag==='div')return`${inside.trim()}\n\n`;if(tag==='br')return'\n';if(tag==='strong'||tag==='b')return`**${inside}**`;if(tag==='em'||tag==='i')return`*${inside}*`;if(tag==='s')return`~~${inside}~~`;if(tag==='a')return`[${inside}](${node.getAttribute('href')||''})`;if(tag==='blockquote')return inside.trim().split('\n').map(line=>`> ${line}`).join('\n')+'\n\n';if(tag==='pre')return`\`\`\`\n${node.innerText}\n\`\`\`\n\n`;if(tag==='li')return`${node.parentElement.tagName==='OL'?`${[...node.parentElement.children].indexOf(node)+1}.`:'-'} ${inside.trim()}\n`;if(tag==='ul'||tag==='ol')return inside+'\n';if(tag==='img')return`![изображение](${node.getAttribute('src')||''})`;if(tag==='hr')return'---\n\n';if(node.classList.contains('check-item'))return`- [${node.querySelector('input')?.checked?'x':' '}] ${node.innerText.trim()}\n`;if(node.classList.contains('document-toc'))return'';return inside}return[...editor.childNodes].map(node=>convert(node)).join('').replace(/\n{3,}/g,'\n\n').trim()+'\n'}
function applyPageSettings(margins='normal',orientation='portrait',pageColor='#ffffff'){document.querySelector('#marginSelect').value=margins;document.querySelector('#orientationSelect').value=orientation;document.querySelector('#pageColor').value=pageColor;editor.style.backgroundColor=pageColor;editor.classList.remove('margins-narrow','margins-wide','orientation-landscape');if(margins!=='normal')editor.classList.add(`margins-${margins}`);if(orientation==='landscape')editor.classList.add('orientation-landscape')}
// Помощник 2026 и быстрые команды версии 15
const assistantPanel=document.querySelector('#assistantPanel'),assistantResult=document.querySelector('#assistantResult'),slashMenu=document.querySelector('#slashMenu');let assistantText='';
function openAssistant(){rememberSelection();assistantPanel.classList.remove('hidden');document.querySelector('#assistantButton').classList.add('active')}
function closeAssistant(){assistantPanel.classList.add('hidden');document.querySelector('#assistantButton').classList.remove('active')}
function assistantSource(){const selection=savedRange?.toString().trim();return selection||getPlainText()}
function tidyText(text){return text.replace(/[ \t]+/g,' ').replace(/\s+([,.;:!?])/g,'$1').replace(/([.!?])(?=\p{L})/gu,'$1 ').replace(/\n{3,}/g,'\n\n').trim()}
function setAssistantResult(text){assistantText=text;assistantResult.textContent=text||'Не удалось создать результат'}
function shortSummary(text){const sentences=(tidyText(text).match(/[^.!?\n]+[.!?]?/g)||[]).map(x=>x.trim()).filter(x=>x.length>20);if(!sentences.length)return tidyText(text);const wanted=Math.min(4,Math.max(2,Math.ceil(sentences.length*.3)));return sentences.slice(0,wanted).map(x=>`• ${x}`).join('\n')}
function formalize(text){return tidyText(text).replace(/\bпривет\b/gi,'Здравствуйте').replace(/\bхочу\b/gi,'планирую').replace(/\bнадо\b/gi,'необходимо').replace(/\bможно\b/gi,'возможно').replace(/\bок\b/gi,'Согласовано')}
document.querySelector('#assistantButton').addEventListener('click',()=>assistantPanel.classList.contains('hidden')?openAssistant():closeAssistant());document.querySelector('#closeAssistantButton').addEventListener('click',closeAssistant);
document.querySelectorAll('[data-assistant]').forEach(button=>button.addEventListener('click',()=>{const source=assistantSource();if(!source){showToast('Добавьте или выделите текст');return}const action=button.dataset.assistant;if(action==='improve')setAssistantResult(tidyText(source));if(action==='summary')setAssistantResult(shortSummary(source));if(action==='formal')setAssistantResult(formalize(source));if(action==='tasks'){const lines=tidyText(source).split(/\n|[.!?]+/).map(x=>x.trim()).filter(x=>x.length>8).slice(0,7);setAssistantResult(lines.map(x=>`☐ ${x}`).join('\n'))}}));
document.querySelector('#assistantInsertButton').addEventListener('click',()=>{const idea=document.querySelector('#assistantPrompt').value.trim();if(!idea){showToast('Введите тему блока');return}setAssistantResult(`${idea}\n\nЦель: ____________________\nКлючевые пункты:\n• ____________________\n• ____________________\nСледующий шаг: ____________________`)});
document.querySelector('#copyAssistantResultButton').addEventListener('click',async()=>{if(!assistantText)return;try{await navigator.clipboard.writeText(assistantText);showToast('Результат скопирован')}catch{showToast('Копирование недоступно')}});document.querySelector('#insertAssistantResultButton').addEventListener('click',()=>{if(!assistantText)return;restoreSelection();document.execCommand('insertHTML',false,`<div class="assistant-inserted">${escapeHtml(assistantText).replace(/\n/g,'<br>')}</div>`);queueAutoSave();updateStats();showToast('Результат вставлен')});
document.querySelector('#compactRibbonButton').addEventListener('click',event=>{document.body.classList.toggle('ribbon-collapsed');const compact=document.body.classList.contains('ribbon-collapsed');event.currentTarget.textContent=compact?'⌄ Лента':'⌃ Лента';localStorage.setItem('myword2026-ribbon',compact?'collapsed':'open')});if(localStorage.getItem('myword2026-ribbon')==='collapsed'){document.body.classList.add('ribbon-collapsed');document.querySelector('#compactRibbonButton').textContent='⌄ Лента'}
document.querySelector('#quickShareButton').addEventListener('click',async()=>{const shareText=`${titleInput.value}\n\n${getPlainText()}`;if(navigator.share){try{await navigator.share({title:titleInput.value,text:shareText});return}catch{}}try{await navigator.clipboard.writeText(shareText);showToast('Документ скопирован для отправки')}catch{showToast('Не удалось скопировать документ')}});
editor.addEventListener('keyup',event=>{if(event.key!=='/')return;const range=window.getSelection()?.getRangeAt(0);if(!range)return;const rect=range.getBoundingClientRect();slashMenu.style.left=`${Math.min(innerWidth-260,Math.max(8,rect.left))}px`;slashMenu.style.top=`${Math.min(innerHeight-270,Math.max(110,rect.bottom+8))}px`;slashMenu.classList.remove('hidden')});
document.querySelectorAll('[data-slash]').forEach(button=>button.addEventListener('mousedown',event=>{event.preventDefault();restoreSelection();document.execCommand('delete');const action=button.dataset.slash;if(action==='h1')document.execCommand('formatBlock',false,'h1');if(action==='check')document.querySelector('#checklistButton').click();if(action==='quote')document.querySelector('#quoteButton').click();if(action==='table')document.querySelector('#tableButton').click();if(action==='date')document.querySelector('#dateButton').click();if(action==='assistant')openAssistant();slashMenu.classList.add('hidden');queueAutoSave()}));document.addEventListener('mousedown',event=>{if(!slashMenu.contains(event.target))slashMenu.classList.add('hidden')});
function applyDocumentExtras(data={}){if(data.watermark)editor.dataset.watermark=data.watermark;else delete editor.dataset.watermark;editor.classList.toggle('page-border',Boolean(data.pageBorder))}
function loadDocumentData(data){titleInput.value=data.title||'Документ';document.querySelector('.window-title').textContent=titleInput.value;editor.innerHTML=data.html||'';documentMeta=data.meta||{author:'',subject:'',keywords:''};editor.lang=data.language||'ru-RU';document.querySelector('#languageSelect').value=editor.lang;if(Number.isFinite(Number(data.wordGoal))){wordGoal=Math.max(0,Number(data.wordGoal));localStorage.setItem('myword2026-word-goal',String(wordGoal))}applyPageSettings(data.margins||'normal',data.orientation||'portrait',data.pageColor||'#ffffff');applyPageSize(data.pageSize||'a4');applyColumns(data.columns||1);applyDocumentExtras(data);updateStats();updateOutline();queueAutoSave()}
function restore(){const saved=localStorage.getItem(STORAGE_KEY);if(saved){try{loadDocumentData(JSON.parse(saved))}catch{localStorage.removeItem(STORAGE_KEY)}}if(localStorage.getItem('myword2026-theme')==='dark'){document.body.classList.add('dark');document.querySelector('#themeButton').textContent='☀️'}updateStats();updateOutline()}
restore();
showRibbon('home');
window.addEventListener('pagehide',()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(getDocumentData()));localStorage.setItem('myword2026-emergency-backup',JSON.stringify({...getDocumentData(),savedAt:new Date().toISOString()}))}catch{}});
